//! Trusted native edits with constraint metadata and independent native editing.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,node:usize){let r=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn input_constraint_metadata_actual_app_trusted_edits_post_paint_and_neighbor(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-input-constraint-metadata-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}button{position:absolute;top:20px;width:100px;height:32px}#raise{left:20px}#lower{left:130px}#zero{left:240px}#remove{left:350px}#check{left:460px}#area{position:absolute;left:20px;top:80px;width:180px;height:70px}#neighbor{position:absolute;left:220px;top:100px;width:160px;height:30px}#stable{position:absolute;left:420px;top:100px}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}</style><form id=form method=post action=https://input-constraints.test/submit><input id=area name=q maxlength=4></form><input id=neighbor value=neighbor><button id=raise>Raise</button><button id=lower>Large</button><button id=zero>Zero</button><button id=remove>Remove</button><button id=check>Check</button><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var x=document.getElementById('area'),events=0;x.oninput=function(e){if(!e.isTrusted)throw 'untrusted input';events++;};document.getElementById('raise').onclick=function(e){if(!e.isTrusted||events!==1||x.value!=='A')throw 'initial edit';x.pattern='[A-Z]+';if(x.pattern!=='[A-Z]+'||x.value!=='A'||x.maxLength!==4)throw 'pattern metadata';};document.getElementById('lower').onclick=function(e){if(!e.isTrusted||events!==2||x.value!=='A😀Z')throw 'paste';x.min=' +20tail';if(x.min!==' +20tail'||x.value!=='A😀Z'||x.maxLength!==4)throw 'min metadata';};document.getElementById('zero').onclick=function(e){if(!e.isTrusted||events!==3||x.value!=='Z')throw 'selection';x.max='-4';};document.getElementById('remove').onclick=function(e){if(!e.isTrusted||events!==3||x.value!=='Z')throw 'max metadata';x.step='any';if(x.step!=='any'||x.max!=='-4'||x.maxLength!==4)throw 'step metadata';};document.getElementById('check').onclick=function(e){if(!e.isTrusted||events!==4||x.value!=='Z😀'||x.value.length!==3||x.defaultValue!==''||x.maxLength!==4||x.pattern!=='[A-Z]+'||x.min!==' +20tail'||x.max!=='-4'||x.step!=='any')throw 'independent editor';var copy=x.cloneNode(true);copy.min='copy';if(copy.value!=='Z😀'||copy.defaultValue!==''||copy.pattern!=='[A-Z]+'||copy.min!=='copy'||x.min!==' +20tail')throw 'clone metadata';if(!x.validity.patternMismatch)throw 'active pattern validation';document.getElementById('form').noValidate=true;document.getElementById('paint').className='done';document.title='Input constraint metadata checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let buttons=["raise","lower","zero","remove","check"].map(|id|node(&app,id));let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==area).unwrap();let rect=(r.x,r.y,r.width,r.height);let initial=app.draw();
 click(&mut app,area);app.text_input('A');assert_eq!(app.forms.controls[&area].value.text(),"A");click(&mut app,buttons[0]);assert_eq!(app.forms.controls[&area].max_length,4);click(&mut app,area);app.key(0x23,true,false,false);app.paste("😀ZQ");assert_eq!(app.forms.controls[&area].value.text(),"A😀Z");click(&mut app,buttons[1]);assert_eq!(app.forms.controls[&area].max_length,4);click(&mut app,area);app.key(0x41,true,false,false);app.paste("Z");assert_eq!(app.forms.controls[&area].value.text(),"Z");click(&mut app,buttons[2]);click(&mut app,buttons[3]);click(&mut app,area);app.key(0x23,true,false,false);app.text_input('😀');assert_eq!(app.forms.controls[&area].value.text(),"Z😀");
 app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}click(&mut app,buttons[4]);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Input constraint metadata checked");let owner=node(&app,"form");let result=app.forms.submit_request(&app.document,owner,None,&app.location,&app.base_location).unwrap();let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};assert_eq!(String::from_utf8(body).unwrap(),"q=Z%F0%9F%98%80");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+430],0xcc2244);let r=app.page.controls.iter().find(|r|r.node==area).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);let(left,top,right,bottom)=(r.x.max(0)as usize,(app.content_top()+r.y-app.scroll).max(0)as usize,(r.x+r.width).min(painted.width as i32)as usize,(app.content_top()+r.y-app.scroll+r.height).min(painted.height as i32)as usize);assert!(left<right&&top<bottom);assert!((top..bottom).any(|y|initial.pixels[y*initial.width+left..y*initial.width+right]!=painted.pixels[y*painted.width+left..y*painted.width+right]),"actual editor paint changes");let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}
